using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;
using sv_f5246553c8964de188cab31686b3e21d.Client;

namespace sv_f5246553c8964de188cab31686b3e21d.Auth;

/// <summary>
/// Server-side AuthenticationStateProvider that provides a hardcoded user
/// and persists auth state into PersistentComponentState so it survives
/// the transition to WebAssembly interactivity.
/// </summary>
public sealed class ServerAuthenticationStateProvider : AuthenticationStateProvider, IDisposable
{
    private static readonly AuthenticationState _authState = CreateAuthState();
    private readonly PersistingComponentStateSubscription _subscription;
    private readonly PersistentComponentState _persistentState;

    public ServerAuthenticationStateProvider(PersistentComponentState persistentComponentState)
    {
        _persistentState = persistentComponentState;
        _subscription = _persistentState.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
        => Task.FromResult(_authState);

    private Task OnPersistingAsync()
    {
        var principal = _authState.User;
        var email = principal.FindFirst(ClaimTypes.Email)?.Value;
        var roles = principal.FindAll(ClaimTypes.Role).Select(c => c.Value).ToArray();

        _persistentState.PersistAsJson(nameof(UserInfo), new UserInfo
        {
            Email = email!,
            Roles = roles,
        });

        return Task.CompletedTask;
    }

    private static AuthenticationState CreateAuthState()
    {
        var claims = new[]
        {
            new Claim(ClaimTypes.Name, "bob@example.com"),
            new Claim(ClaimTypes.Email, "bob@example.com"),
            new Claim(ClaimTypes.Role, "User"),
            new Claim(ClaimTypes.Role, "Editor"),
        };

        var identity = new ClaimsIdentity(claims, authenticationType: "HardCoded");
        return new AuthenticationState(new ClaimsPrincipal(identity));
    }

    public void Dispose()
    {
        _subscription.Dispose();
    }
}

